def normalize(raw: str) -> str:
    return raw.strip().lower()

def validate(value: str) -> bool:
    return bool(value) and len(value) <= 12

def process(raw: str) -> str | None:
    value = normalize(raw)
    if not validate(value):
        return None
    return value

